@code {
    private List<TaskItem> _tasks = new();
    private string _searchTerm = "";
    private bool _isLoading = true;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = _tasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(_searchTerm))
        {
            filtered = filtered.Where(t =>
                t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        return filtered.ToList();
    }

    private void HandleSearchChanged(string term)
    {
        _searchTerm = term;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                _tasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            _tasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}
"}

